import { PlaneGeometry, Mesh, Group, MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { imageUrl, textContent, colors, scenePosition } = config;
  const { position, rotation, scale } = scenePosition;

  const group = new Group();

  // ── Texture plane ──────────────────────────────────────────────────
  const texture = ctx.textureLoader.load(imageUrl);
  // If the texture is part of an atlas, set UV repeat/offset.
  // Source rect is (0, 0, 512, 320). We assume the loaded image may be larger.
  const img = texture.image;
  if (img && img.width && img.height) {
    const srcW = 512;
    const srcH = 320;
    texture.repeat.set(srcW / img.width, srcH / img.height);
    // UV origin is bottom-left; source rect top-left, so offset y = 1 - srcH/img.height
    texture.offset.set(0, 1 - srcH / img.height);
  } else {
    // Fallback: assume texture is exactly the region
    texture.repeat.set(1, 1);
    texture.offset.set(0, 0);
  }

  const aspect = 512 / 320; // ≈1.6
  const geometry = new PlaneGeometry(aspect, 1);
  const material = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
  });
  const plane = new Mesh(geometry, material);
  group.add(plane);

  // ── Text “Features 2” ──────────────────────────────────────────────
  // Use headline size from design tokens (0.34 scene units), Lora serif weight 400.
  const textMesh = ctx.fontAtlas.createText(textContent.text, {
    fontSize: 0.34,
    fontFamily: 'Lora',
    fontWeight: 400,
    color: colors.paper || '#e8ecf2',
    align: 'center',
    baseline: 'middle',
  });
  textMesh.position.z = 0.01; // slightly above the plane
  group.add(textMesh);

  // ── Placement ──────────────────────────────────────────────────────
  group.position.copy(position);
  group.rotation.set(rotation.x, rotation.y, rotation.z);
  group.scale.copy(scale);

  // ── Handlers (none required) ───────────────────────────────────────
  group.userData.handlers = {};

  // ── Cleanup ────────────────────────────────────────────────────────
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
    // No GSAP timelines to kill.
  };

  return group;
}
